3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
9	import org.springframework.web.bind.annotation.RequestBody;
10	
11	/**
12	 * First step of {@code POST /api/owners}: rejects a body that is missing or blank in any
13	 * required field, reporting every offending field at once. Publishes the validated body
14	 * for {@link BuildOwner} so the request is read only here.
15	 */
16	public class ValidateOwnerFields {
17	
18	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
19	            throws MissingOwnerFieldsException {
20	        List<String> missing = new ArrayList<>();
21	        require("firstName", request.getFirstName(), missing);
22	        require("lastName", request.getLastName(), missing);
23	        // Address is required once normalized, so a value that is blank after
24	        // normalization (e.g. only whitespace) is rejected here rather than stored empty.
25	        require("address", AddressNormalizer.normalize(request.getAddress()), missing);
26	        require("city", request.getCity(), missing);
27	        require("telephone", request.getTelephone(), missing);
28	        if (!missing.isEmpty()) {
29	            throw new MissingOwnerFieldsException(missing);
30	        }
31	        validated.set(request);
32	    }
33	
34	    private static void require(String name, String value, List<String> missing) {
35	        if (value == null || value.isBlank()) {
36	            missing.add(name);
37	        }
38	    }
39	}
